/* Nice Otter 15 by elijahgummer — https://uiverse.io/elijahgummer/nice-otter-15 */
.input {
  width: 200px;
  padding: 12px;
  border: 2px solid #3498db;
  border-radius: 8px;
  outline: none;
  font-size: 18px;
  transition: border-color 0.3s, box-shadow 0.3s, transform 0.3s;
  background-color: #fff;
  color: #333;
  box-sizing: border-box;
}

.input:focus {
  border-color: #2980b9;
  box-shadow: 0 0 15px rgba(52, 152, 219, 0.5);
  transform: scale(1.02);
}

.input::placeholder {
  color: #aaa;
  font-style: italic;
}

.input:hover {
  background-color: #f0f8ff;
}
